def transform(grid):
    h, w = len(grid), len(grid[0])
    # The solid 2-line is a barrier. Move the colored object up to it,
    # then mark the parallel line immediately behind the object with 8.
    barrier = None
    for r in range(h):
        if all(v == 2 for v in grid[r]):
            barrier = ('h', r)
            break
    if barrier is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                barrier = ('v', c)
                break
    if barrier is None:
        return [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    axis, pos = barrier
    coords = [(r,c) for r in range(h) for c in range(w)
              if grid[r][c] not in (bg, 2)]
    if not coords:
        return [row[:] for row in grid]
    # Translate the object toward the barrier until its leading edge is adjacent.
    if axis == 'h':
        lead = max(r for r,c in coords) if pos > h//2 else min(r for r,c in coords)
        delta = (pos - 1 - lead) if pos > h//2 else (pos + 1 - lead)
        dr, dc = delta, 0
        behind = min(r+dr for r,c in coords) - 1 if pos > h//2 else max(r+dr for r,c in coords) + 1
        if not (0 <= behind < h):
            behind = None
    else:
        lead = max(c for r,c in coords) if pos > w//2 else min(c for r,c in coords)
        delta = (pos - 1 - lead) if pos > w//2 else (pos + 1 - lead)
        dr, dc = 0, delta
        behind = min(c+dc for r,c in coords) - 1 if pos > w//2 else max(c+dc for r,c in coords) + 1
        if not (0 <= behind < w):
            behind = None
    out = [[bg]*w for _ in range(h)]
    # Preserve the separator and shift each non-background object cell.
    if axis == 'h':
        out[pos] = grid[pos][:]
    else:
        for r in range(h): out[r][pos] = 2
    for r,c in coords:
        nr,nc = r+dr,c+dc
        if 0 <= nr < h and 0 <= nc < w:
            out[nr][nc] = grid[r][c]
    if behind is not None:
        if axis == 'h':
            out[behind] = [8]*w
        else:
            for r in range(h): out[r][behind] = 8
    return out

